//! Differential oracle test against `gopkg.in/yaml.v3`.
//!
//! Reads a TSV of `<spec>\t<base64(expected_yaml)>` lines (generated by the Go
//! oracle in this crate's dev notes) from the path in `CF_GOYAML_ORACLE`, parses
//! each spec into a [`GoValue`], marshals it with [`cf_goyaml::marshal`], and
//! asserts byte-equality with the captured `yaml.Marshal` output.
//!
//! The test is skipped (passes trivially) when the env var is unset, so it never
//! blocks a normal `cargo test` run while remaining available for the parity gate.

use cf_gojson::{GoMap, GoValue};

#[test]
fn oracle_byte_parity() {
    let Ok(path) = std::env::var("CF_GOYAML_ORACLE") else {
        eprintln!("CF_GOYAML_ORACLE unset; skipping oracle parity test");
        return;
    };
    let data = std::fs::read_to_string(&path).expect("read oracle file");
    let mut total = 0usize;
    let mut fail = 0usize;
    for (lineno, line) in data.lines().enumerate() {
        if line.is_empty() {
            continue;
        }
        let (spec, b64) = line.split_once('\t').expect("tab-separated");
        let expected = b64_decode(b64);
        let mut p = Parser {
            b: spec.as_bytes(),
            i: 0,
        };
        let value = p.parse_value();
        let got = cf_goyaml::marshal(&value);
        total += 1;
        if got != expected {
            fail += 1;
            if fail <= 20 {
                eprintln!(
                    "MISMATCH line {} spec={:?}\n  expected={:?}\n  got     ={:?}",
                    lineno + 1,
                    spec,
                    String::from_utf8_lossy(&expected),
                    String::from_utf8_lossy(&got),
                );
            }
        }
    }
    eprintln!("oracle: {total} cases, {fail} mismatches");
    assert_eq!(fail, 0, "{fail}/{total} oracle mismatches");
}

/// Mini-DSL parser matching the Go generator:
/// `I<int> U<uint> F<bits> Bt Bf N S<b64> A(..;..) M(b64=val;..)`.
struct Parser<'a> {
    b: &'a [u8],
    i: usize,
}

impl Parser<'_> {
    fn peek(&self) -> u8 {
        self.b[self.i]
    }
    fn parse_value(&mut self) -> GoValue {
        match self.peek() {
            b'I' => {
                self.i += 1;
                let s = self.take_token();
                GoValue::Int(s.parse().unwrap())
            }
            b'U' => {
                self.i += 1;
                let s = self.take_token();
                GoValue::Uint(s.parse().unwrap())
            }
            b'F' => {
                self.i += 1;
                let s = self.take_token();
                let bits: u64 = s.parse().unwrap();
                GoValue::Float(f64::from_bits(bits))
            }
            b'B' => {
                self.i += 1;
                let t = self.b[self.i];
                self.i += 1;
                GoValue::Bool(t == b't')
            }
            b'N' => {
                self.i += 1;
                GoValue::Null
            }
            b'S' => {
                self.i += 1;
                let s = self.take_token();
                GoValue::Str(String::from_utf8(b64_decode(&s)).unwrap())
            }
            b'A' => {
                self.i += 1; // 'A'
                self.expect(b'(');
                let mut items = Vec::new();
                if self.peek() != b')' {
                    loop {
                        items.push(self.parse_value());
                        if self.peek() == b';' {
                            self.i += 1;
                        } else {
                            break;
                        }
                    }
                }
                self.expect(b')');
                GoValue::Array(items)
            }
            b'M' => {
                self.i += 1; // 'M'
                self.expect(b'(');
                let mut m = GoMap::new_struct();
                if self.peek() != b')' {
                    loop {
                        // key is base64 up to the '>' kv separator
                        let kb = self.take_until(b'>');
                        self.expect(b'>');
                        let key = String::from_utf8(b64_decode(&kb)).unwrap();
                        let val = self.parse_value();
                        m.push(key, val);
                        if self.peek() == b';' {
                            self.i += 1;
                        } else {
                            break;
                        }
                    }
                }
                self.expect(b')');
                GoValue::Map(m)
            }
            other => panic!("bad spec char {other:?} at {}", self.i),
        }
    }

    fn expect(&mut self, c: u8) {
        assert_eq!(self.b[self.i], c, "expected {} at {}", c as char, self.i);
        self.i += 1;
    }

    /// Token = run of base64 chars / digits / sign until a DSL delimiter.
    fn take_token(&mut self) -> String {
        let start = self.i;
        while self.i < self.b.len() && !matches!(self.b[self.i], b';' | b')') {
            self.i += 1;
        }
        String::from_utf8(self.b[start..self.i].to_vec()).unwrap()
    }

    fn take_until(&mut self, stop: u8) -> String {
        let start = self.i;
        while self.i < self.b.len() && self.b[self.i] != stop {
            self.i += 1;
        }
        String::from_utf8(self.b[start..self.i].to_vec()).unwrap()
    }
}

/// Standard base64 decode (with '=' padding).
fn b64_decode(s: &str) -> Vec<u8> {
    fn val(c: u8) -> i32 {
        match c {
            b'A'..=b'Z' => (c - b'A') as i32,
            b'a'..=b'z' => (c - b'a' + 26) as i32,
            b'0'..=b'9' => (c - b'0' + 52) as i32,
            b'+' => 62,
            b'/' => 63,
            _ => -1,
        }
    }
    let mut out = Vec::new();
    let mut buf = 0i32;
    let mut bits = 0;
    for &c in s.as_bytes() {
        if c == b'=' {
            break;
        }
        let v = val(c);
        if v < 0 {
            continue;
        }
        buf = (buf << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((buf >> bits) as u8 & 0xFF);
        }
    }
    out
}
